WITH s AS (
  DELETE FROM public.sesiones_usuario
   WHERE expira_en < now() - interval '7 days' OR revocado_en < now() - interval '7 days'
  RETURNING 1
), t AS (
  DELETE FROM public.tokens_recuperacion WHERE expira_en < now() - interval '1 day' RETURNING 1
), a AS (
  DELETE FROM public.auditoria_accesos WHERE creado_en < now() - interval '365 days' RETURNING 1
)
SELECT (SELECT count(*) FROM s) AS sesiones, (SELECT count(*) FROM t) AS tokens, (SELECT count(*) FROM a) AS accesos;
